'use strict';
/* Basic dictionary spell check. Uses the bundled wordlist (words.json,
 * generated by scripts/make-wordlist.js from public text corpora on the
 * build machine plus a core common-words list). Grammar checking is NOT
 * implemented: grammar error counts are always 0 (see README). */
const fs = require('node:fs');
const path = require('node:path');

let cache = null;
function loadWords() {
  if (cache) return cache;
  try {
    const arr = JSON.parse(fs.readFileSync(path.join(__dirname, 'words.json'), 'utf8'));
    cache = new Set(arr);
  } catch (_) { cache = new Set(); }
  return cache;
}

const ALLOWLIST = new Set(('seonfix wordpress woocommerce yoast elementor divi avada astra gutenberg shopify wix squarespace webflow hubspot mailchimp google analytics facebook instagram linkedin youtube twitter tiktok pinterest whatsapp seo sem smo cms css html javascript php mysql jquery bootstrap react angular vue nodejs api apis url urls http https www com org net io ai chatgpt gemini openai anthropic ollama screaming frog mdimrankhan imran khan bangladesh dhaka norwich norfolk schema json xml svg png jpg jpeg gif webp favicon sitemap robots canonical hreflang backlink backlinks keyword keywords meta serps snippet snippets breadcrumb breadcrumbs permalink permalinks slug slugs widget widgets plugin plugins theme themes hosting cpanel ssl tls cdn dns mx txt spf dkim dmarc ga4 gtm gsc wordpresses').split(/\s+/));

/* Count likely spelling errors in plain text: lowercase alphabetic tokens
 * (len >= 3) not in the dictionary or allowlist. Tokens containing digits
 * or apostrophe-joined contractions are handled leniently. */
function countSpellingErrors(text, words = loadWords()) {
  if (!text) return { errors: 0, tokens: 0, unknown: [] };
  const raw = String(text).toLowerCase().match(/[a-z][a-z']*[a-z]|[a-z]{2}/g) || [];
  let errors = 0; let tokens = 0;
  const unknown = new Set();
  for (const tok of raw) {
    if (tok.length < 3) continue;
    tokens++;
    const base = tok.replace(/'s$/, '').replace(/s'$/, '');
    if (words.has(tok) || words.has(base) || ALLOWLIST.has(tok) || ALLOWLIST.has(base)) continue;
    // plural / possessive / common suffix leniency
    if (base.endsWith('s') && words.has(base.slice(0, -1))) continue;
    if (base.endsWith('es') && words.has(base.slice(0, -2))) continue;
    if (base.endsWith('ing') && (words.has(base.slice(0, -3)) || words.has(base.slice(0, -3) + 'e'))) continue;
    if (base.endsWith('ed') && (words.has(base.slice(0, -2)) || words.has(base.slice(0, -2) + 'e') || words.has(base.slice(0, -1)))) continue;
    if (base.endsWith('ly') && words.has(base.slice(0, -2))) continue;
    if (base.endsWith('ies') && words.has(base.slice(0, -3) + 'y')) continue;
    errors++;
    if (unknown.size < 50) unknown.add(tok);
  }
  return { errors, tokens, unknown: [...unknown] };
}

module.exports = { loadWords, countSpellingErrors, ALLOWLIST };
